import re

from past.utils import old_div
from robot.api import logger

from ta_egate_cmd_parser.egate_output_parser_base import EgateDispCommandsOutputParser
from ta_egate_cmd_parser.egate_command_base import EgateCommandBase
from ta_egate_cmd_parser.utils.converters import create_dict_with_key

PASS_FAIL_REGEXP = re.compile(r'(\d+\/\d+)')
FREQ_CHANGE_REGEXP = re.compile(r'(\d+\s:\s\d+\s:\s\d+\s:\s\d+\s:\s\d+\s:\s\d+\s:\s\d+\s:\s\d+\s:\s\d+\s:\s\d+)')
RADAR_REGEXP = re.compile(r'(\d+\s:\s\d+\s:\s\d+\s:\s\d+\s:\s\d+\s:\s\d+\s:\s\d+\s:\s\d+\s:\s\d+\s:\s\d+)')


def parse_pass_fail_rate(value):
    """
    Parse value from "'Value' column of laa_rrh_counter cmd output with type=pass_fail

    :param value: column value as string
    :return: dict with pass, fail and average_fail_rate

    Example
    input:      1/10 : 2/9 : 3/8 : 4/7 : 5/6 : 6/5 : 7/4 : 8/3 : 9/2 : 10/1
    output:     [{'fail': 10, 'average_fail_rate': 91, 'pass': 1},
    ...          {'fail': 9, 'average_fail_rate': 82, 'pass': 2},
    ...          {'fail': 8, 'average_fail_rate': 73, 'pass': 3},
    ...          {'fail': 7, 'average_fail_rate': 64, 'pass': 4},
    ...          {'fail': 6, 'average_fail_rate': 55, 'pass': 5},
    ...          {'fail': 5, 'average_fail_rate': 45, 'pass': 6},
    ...          {'fail': 4, 'average_fail_rate': 36, 'pass': 7},
    ...          {'fail': 3, 'average_fail_rate': 27, 'pass': 8},
    ...          {'fail': 2, 'average_fail_rate': 18, 'pass': 9},
    ...          {'fail': 1, 'average_fail_rate': 9, 'pass': 10}]
    """
    channels_pass_fail = re.findall(PASS_FAIL_REGEXP, value)

    if channels_pass_fail:
        return covert_pass_fail_rate_to_average_fail_rate(channels_pass_fail)
    else:
        return value


def parse_freq_change(value):
    """
    Parse value from "'Value' column of laa_rrh_counter cmd output with type=freq_change

    :param value: column value as string
    :return: list of freq change for channels

    Example:
    input:
    output:    ['0', '0', '1', '0', '1', '0', '0', '0', '0', '0']
    """
    freq_change = re.search(FREQ_CHANGE_REGEXP, value)

    if freq_change:
        channel_freq_change = freq_change.group(0).split(' : ')
        return channel_freq_change
    else:
        return value


def parse_radar(value):
    """
    Parse value from "'Value' column of laa_rrh_counter cmd output with type=radar

    :param value: column value as string
    :return: list of freq change for channels

    Example:
    input:
    output:    ['0', '0', '1', '0', '1', '0', '0', '0', '0', '0']
    """
    radar = re.search(RADAR_REGEXP, value)

    if radar:
        channel_radar = radar.group(0).split(' : ')
        return channel_radar
    else:
        return value


def covert_pass_fail_rate_to_average_fail_rate(channels_pass_fail):
    """

    :param channels_pass_fail:
    :return:
    """
    results = []
    for channel_results in channels_pass_fail:
        pass_rate = float(channel_results.split('/')[0])
        fail_rate = float(channel_results.split('/')[1])

        results.append({
            "pass": int(pass_rate),
            "fail": int(fail_rate),
            "average_fail_rate": int(round(old_div((100 * fail_rate), (pass_rate + fail_rate))))
        })
    return results


class LaaRrhCountersFailure(Exception):
    """
    Exception class for laa_rrh_counters
    """
    pass


class LaaRrhCounters(EgateCommandBase):
    """
    Command parser for command 'laa_rrh_counters'.
    """

    def __init__(self, **params):
        """

        :param params:
        """
        super(LaaRrhCounters, self).__init__()
        self.command = 'laa_rrh_counters'
        self.params = params
        self.executed_phrase = r'.*?eNB-\d+\srfh-\d+.*?EGATE>'
        self.fail_regexp = 'Error'
        self.to_execute = self.command
        self._build_command()
        self.parsers = {
            'freq_change': self._parse_with_type_freq_change,
            'pass_fail': self._parse_with_type_pass_fail,
            'radars': self._parse_with_type_radar
        }
        logger.debug('{}: {} command to execute:\n{}'.format(self.__class__.__name__, self.command, self.to_execute))

    def execute(self, egate_id=0):
        """
        Execute egate cmd.

        :return: None
        """
        self.executed_phrase = '.*?EGATE>'
        status, output = super(LaaRrhCounters, self).execute(egate_id=egate_id, command=self.to_execute)
        if status:
            return status, output
        else:
            raise LaaRrhCountersFailure(output)

    def execute_and_parse(self, egate_id=0):
        """
        Execute egate cmd and parse its output.

        :return: Parsed cmd output
        """
        status, output = super(LaaRrhCounters, self).execute(egate_id=egate_id, command=self.to_execute)
        if status:
            parsed_output = self._parse_laa_rrh_counter_output(output)
            logger.debug('{}: {} cmd parsed output:\n{}'.format(self.__class__.__name__, self.command, parsed_output))
            return parsed_output
        else:
            raise LaaRrhCountersFailure(output)

    def _build_command(self):
        """
        Build laa_rrh_counters command.

        :return: None
        """
        for param, value in list(self.params.items()):
            if param in ['check', 'clear', 'display']:
                self.to_execute += ' {}'.format(param)
            else:
                self.to_execute += ' {}={}'.format(param, value)

    def _parse_laa_rrh_counter_output(self, output):
        try:
            counters_type = self.params['type']
            return self.parsers[counters_type](output)
        except KeyError:
            return output

    def _parse_with_type_pass_fail(self, cmd_output):
        """

        :param cmd_output:
        :return:
        """
        cmd_parser = EgateDispCommandsOutputParser(cmd_output)
        cmd_parser.parse_column_value_with_custom_function('Value', parse_pass_fail_rate)
        output = cmd_parser.get_list_of_output_parsed_lines()
        return self._aggregate_subband_results(output)

    def _parse_with_type_freq_change(self, cmd_output):
        """

        :param cmd_output:
        :return:
        """
        cmd_parser = EgateDispCommandsOutputParser(cmd_output)
        cmd_parser.parse_column_value_with_custom_function('Value', parse_freq_change)
        output = cmd_parser.get_list_of_output_parsed_lines()
        return create_dict_with_key(key='LAA COUNTER',
                                    list_of_output_parsed_lines=output)

    def _parse_with_type_radar(self, cmd_output):
        """

        :param cmd_output:
        :return:
        """
        cmd_parser = EgateDispCommandsOutputParser(cmd_output)
        cmd_parser.parse_column_value_with_custom_function('Value', parse_radar)
        output = cmd_parser.get_list_of_output_parsed_lines()
        return create_dict_with_key(key='LAA COUNTER',
                                    list_of_output_parsed_lines=output)

    def _aggregate_subband_results(self, parsed_lines):
        parsed_data = {}
        current_subband = None
        for idx, line in enumerate(parsed_lines[1:]):
            subband = re.search(r'Airscale Subband#\d{1}:', line[0])
            if subband:
                current_subband = subband.group(0)
            if current_subband:
                if current_subband not in list(parsed_data.keys()):
                    parsed_data[current_subband] = []
                else:
                    parsed_data[current_subband].extend(line[1])
            else:
                parsed_data[line[0]] = line[1]
        return parsed_data
